PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE warehouses (
  warehouse_id TEXT PRIMARY KEY,
  warehouse_name TEXT NOT NULL
, street_address TEXT, city TEXT, state TEXT, zip_code TEXT);
CREATE TABLE products (     id TEXT PRIMARY KEY,     warehouse_id TEXT NOT NULL,     item_number TEXT,     product_id TEXT,     product_name TEXT NOT NULL,     aisle TEXT,     bay TEXT,     is_wrong INTEGER DEFAULT 0,     is_discontinued INTEGER DEFAULT 0,     product_url TEXT,     updated_at TEXT, category TEXT, sku TEXT,     FOREIGN KEY (warehouse_id) REFERENCES warehouses(warehouse_id) ON DELETE CASCADE ON UPDATE CASCADE );
CREATE INDEX idx_products_flagged ON products(warehouse_id, is_wrong);
CREATE INDEX idx_products_warehouse_aisle ON products(warehouse_id, aisle, bay);
CREATE INDEX idx_products_warehouse_search ON products(warehouse_id, item_number, product_id);
CREATE INDEX idx_products_warehouse_category ON products(warehouse_id, category);
